<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import crew from '../crew.json'
type Character={name:string;owner:string;class:string;level:number;color?:string;status?:string}
type Dashboard={activePlayers:number;totalLevels:number;deaths:number;playedHours:number;characters:Character[];events:{title:string;detail:string;type?:string}[]}
const route=ref(location.hash.slice(1)||"overview"), menu=ref(false), connected=ref(false), loading=ref(true), now=ref(Date.now()), showForm=ref(false), submitted=ref(false)
const crewMembers=ref<Array<{name:string;character:string;class:string;faction:string;roles?:string}>>(crew)
const sheetCsv='https://docs.google.com/spreadsheets/d/1SZIHizrbutMwKg25SF9vGVLSEMo_NIogMF4ZiJ20NcY/export?format=csv&gid=186545892'
const classIcons:Record<string,string>={Druid:'class_druid',Hunter:'class_hunter',Mage:'class_mage',Paladin:'class_paladin',Priest:'class_priest',Rogue:'class_rogue',Shaman:'class_shaman',Warlock:'class_warlock',Warrior:'class_warrior'}
function classIcon(className:string){const key=className.trim();return classIcons[key]?`https://wow.zamimg.com/images/wow/icons/medium/${classIcons[key]}.jpg`:''}
function factionIcon(faction:string){return faction==='Horde'?'https://wow.zamimg.com/images/wow/icons/tiny/side_horde.gif':faction==='Alliance'?'https://wow.zamimg.com/images/wow/icons/tiny/side_alliance.gif':''}
function parseCsv(csv:string){const rows=csv.trim().split(/\r?\n/).map(row=>row.split(/,(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)/).map(cell=>cell.replace(/^\"|\"$/g,'').replace(/\"\"/g,'\"')));const headers=rows.shift()?.map(h=>h.trim())||[];return rows.filter(row=>row.some(Boolean)).map(row=>{const item=Object.fromEntries(headers.map((header,index)=>[header,row[index]||'']));return {name:item['Your name / nickname']||'',character:'',class:item['Which class do you want to play?']||'',faction:item['Faction']||'',roles:item['Which roles are you interested in?']||''}}).filter(item=>item.name)}
const factions={Horde:['Orc','Undead','Tauren','Troll','Skyborne'],Alliance:['Human','Dwarf','Night Elf','Gnome','Skyborne']}
const combinations:Record<string,string[]>={Druid:['Night Elf','Tauren','Skyborne'],Hunter:['Human','Dwarf','Night Elf','Orc','Tauren','Troll','Skyborne'],Mage:['Human','Gnome','Undead','Troll','Skyborne'],Paladin:['Human','Dwarf','Undead'],Priest:['Human','Dwarf','Night Elf','Gnome','Undead','Troll'],Rogue:['Human','Dwarf','Night Elf','Gnome','Orc','Undead','Troll','Skyborne'],Shaman:['Dwarf','Orc','Tauren','Troll','Skyborne'],Warlock:['Human','Gnome','Orc','Undead','Troll'],Warrior:['Human','Dwarf','Night Elf','Gnome','Orc','Undead','Tauren','Troll','Skyborne']}
const form=reactive({name:'',faction:'',race:'',character:'',class:'',characters:[] as {character:string;race:string;class:string}[],launch:'yes',note:''})
const signupUrl='https://docs.google.com/forms/d/e/1FAIpQLSfbhURjHavL3GG5T9xTN_cvn3ZEy5uBthUCJQM5YTNDLmPbdg/viewform'
function openSignup(){showForm.value=true}
const factionRaces=computed(()=>factions[form.faction as 'Horde'|'Alliance'] || [])
const availableClasses=computed(()=>Object.keys(combinations).filter(name=>form.race && combinations[name].includes(form.race)))
function addCharacter(){if(form.character&&form.race&&form.class){form.characters.push({character:form.character,race:form.race,class:form.class});form.character='';form.race='';form.class=''}}
function removeCharacter(index:number){form.characters.splice(index,1)}
async function submitForm(){const body=new URLSearchParams({'form-name':'crew-signup',name:form.name,faction:form.faction,race:form.race,character:form.character,class:form.class,characters:JSON.stringify(form.characters),launch:form.launch,note:form.note});await fetch('/',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});submitted.value=true}
const data=ref<Dashboard>({activePlayers:0,totalLevels:0,deaths:0,playedHours:0,characters:[],events:[]})
const pages=[['overview','OVERVIEW'],['crew','THE CREW'],['characters','CHARACTERS'],['chronicle','CHRONICLE']]
const title=computed(()=>pages.find(p=>p[0]===route.value)?.[1]||'OVERVIEW')
function navigate(to:string){route.value=to;menu.value=false;location.hash=to}
onMounted(async()=>{addEventListener('hashchange',()=>route.value=location.hash.slice(1)||'overview');try{const sheet=await fetch(sheetCsv);if(sheet.ok){const members=parseCsv(await sheet.text());if(members.length)crewMembers.value=members as typeof crewMembers.value}}catch{ /* keep empty roster when unavailable */ }try{const r=await fetch('/api/dashboard');const type=r.headers.get('content-type')||'';if(r.ok&&type.includes('application/json'))data.value=await r.json()}catch{ /* local Vite has no Netlify function; keep zero state */ }finally{loading.value=false}})
const launchAt=new Date("2026-11-05T00:00:00+01:00").getTime()
const countdown=computed(()=>{const s=Math.max(0,Math.floor((launchAt-now.value)/1000));return {days:Math.floor(s/86400),hours:Math.floor(s%86400/3600),minutes:Math.floor(s%3600/60),seconds:s%60}})
setInterval(()=>now.value=Date.now(),1000)
</script>
<template><div class="app-shell"><header class="topbar"><button class="mobile-menu" @click="menu=!menu">☰</button><div class="brand" @click="navigate('overview')"><div class="brand-mark">✦</div><div><b>CZECHDREAM</b><span>FOREVER</span></div></div><nav :class="{open:menu}"><a v-for="page in pages" :key="page[0]" :class="{selected:route===page[0]}" @click="navigate(page[0])">{{page[1]}}</a></nav><div class="top-actions"><span class="public-badge">PUBLIC GUILD DASHBOARD</span></div></header><main><section v-if="route==='overview'" class="launch-banner"><div><div class="kicker"><i></i> WORLD OF WARCRAFT: FOREVER</div><h2>THE JOURNEY BEGINS</h2><p>Global launch · 5 November 2026 · 00:00 CET</p></div><div class="countdown"><div><strong>{{String(countdown.days).padStart(2,'0')}}</strong><small>DAYS</small></div><b>:</b><div><strong>{{String(countdown.hours).padStart(2,'0')}}</strong><small>HOURS</small></div><b>:</b><div><strong>{{String(countdown.minutes).padStart(2,'0')}}</strong><small>MIN</small></div><b>:</b><div><strong>{{String(countdown.seconds).padStart(2,'0')}}</strong><small>SEC</small></div></div></section><section v-if="route==='overview'" class="crew-signup-area"><div class="kicker"><i></i> CZECHDREAM CREW</div><h2>ZBYTOČNÍ ARE BACK!</h2><p>Tell us what you are playing and what you want to focus on in Forever.</p><div class="crew-list"><div v-if="!crewMembers.length" class="empty-state">Zatiaľ sa nepridal nikto. Buď prvý.</div><div v-for="member in crewMembers" :key="member.name" class="crew-member"><strong>{{member.name}}</strong><span>{{member.character}}</span><span class="member-classes"><span v-for="className in member.class.split(',')" :key="className"><img v-if="classIcon(className)" :src="classIcon(className)" :alt="className.trim()" :title="className.trim()"></span></span><span class="member-faction"><img v-if="factionIcon(member.faction)" :src="factionIcon(member.faction)" :alt="member.faction">{{member.faction}}</span><span class="member-roles">{{member.roles}}</span></div></div><button class="gold-button join-button" @click="openSignup">JOIN THE CREW</button><div v-if="showForm" class="form-modal"><button type="button" class="form-close" @click="showForm=false">×</button><iframe :src="signupUrl" title="CzechDream Forever signup form"></iframe></div><form v-if="false" class="signup-form" name="crew-signup" .prevent="submitForm"><div v-if="submitted" class="success">Hotovo. Si zapísaný v CzechDream crew.</div><template v-else><input v-model="form.name" name="name" required placeholder="Tvoje meno / nick"><div class="faction-picker"><button type="button" :class="{chosen:form.faction==='Horde'}" @click="form.faction='Horde';form.race='';form.class=''"><img src="https://wow.zamimg.com/images/wow/icons/tiny/side_horde.gif" alt=""> HORDE</button><button type="button" :class="{chosen:form.faction==='Alliance'}" @click="form.faction='Alliance';form.race='';form.class=''"><img src="https://wow.zamimg.com/images/wow/icons/tiny/side_alliance.gif" alt=""> ALLIANCE</button></div><div class="choice-block"><label>RASA</label><div class="choice-grid"><button v-for="race in factionRaces" :key="race" type="button" :class="{chosen:form.race===race}" @click="form.race=race;form.class=''">{{race}}</button></div></div><div class="choice-block"><label>CLASSA</label><div class="choice-grid"><button v-for="className in availableClasses" :key="className" type="button" :class="{chosen:form.class===className}" @click="form.class=className">{{className}}</button></div></div><input v-model="form.character" name="character" required placeholder="Meno postavy"><button class="ghost-button add-character" type="button" @click="addCharacter">+ PRIDAŤ ĎALŠIU POSTAVU</button><div v-if="form.characters.length" class="planned-characters"><div v-for="(character,index) in form.characters" :key="index"><strong>{{character.character}}</strong><span>{{character.race}} · {{character.class}}</span><button type="button" @click="removeCharacter(index)">×</button></div></div><textarea v-model="form.note" name="note" placeholder="Poznámka"></textarea><button class="gold-button" type="submit">ZAPÍSAŤ MA →</button></template></form></section><section v-if="route==='overview'" class="hero"><div class="hero-copy"><div class="kicker"><i></i> THE CZECHDREAM GUILD</div><h1>ZBYTOČNÍ<br><em>SÚ SPÄŤ.</em></h1><p>A shared chronicle of every level, death, victory and ridiculous moment in Azeroth.</p><div class="hero-buttons"><button class="gold-button" @click="connected=!connected">{{connected?'BRIDGE CONNECTED':'CONNECT YOUR BRIDGE'}} <span>→</span></button><button class="ghost-button" @click="navigate('chronicle')">VIEW CHRONICLE</button></div></div><div class="hero-art"><div class="moon"></div><div class="mountain">⚔</div><div class="hero-tag"><strong>SEASON ONE</strong><span>THE JOURNEY BEGINS</span></div></div></section><section class="section-head"><div><div class="kicker">GUILD INTELLIGENCE</div><h2>{{title}}</h2></div><div class="live"><i></i>{{connected?'BRIDGE ONLINE':'AWAITING SYNC'}}</div></section><section v-if="route==='overview'" class="stats"><article><span class="stat-icon">♙</span><div><small>ACTIVE PLAYERS</small><strong>{{data.activePlayers}}</strong><label>from synced data</label></div></article><article><span class="stat-icon gold">♜</span><div><small>TOTAL LEVELS</small><strong>{{data.totalLevels}}</strong><label>across all characters</label></div></article><article><span class="stat-icon red">☠</span><div><small>DEATHS RECORDED</small><strong>{{data.deaths}}</strong><label>from synced events</label></div></article><article><span class="stat-icon purple">◈</span><div><small>TIME TOGETHER</small><strong>{{data.playedHours}}h</strong><label>from synced sessions</label></div></article></section><section v-if="route==='overview'||route==='crew'||route==='characters'" class="content-grid"><article class="panel wide"><div class="panel-title"><div><div class="kicker">THE PARTY</div><h3>{{route==='crew'?'CREW MEMBERS':'CHARACTER ROSTER'}}</h3></div></div><div class="roster-row header-row"><span>CHARACTER</span><span>CLASS</span><span>LEVEL</span><span>STATUS</span></div><div v-if="loading" class="empty-state">Loading guild data...</div><div v-else-if="!data.characters.length" class="empty-state">No characters synced yet. Connect a CzechDream Bridge.</div><div v-for="player in data.characters" v-else :key="player.name" class="roster-row"><div class="character"><span :class="['portrait',player.color]">{{player.name[0]}}</span><div><b>{{player.name}}</b><small>{{player.owner}}</small></div></div><span class="class-name">{{player.class}}</span><b class="level">{{player.level}}</b><span :class="['player-status',player.status]"><i></i>{{player.status}}</span></div></article><article v-if="route==='overview'" class="panel"><div class="panel-title"><div><div class="kicker">RECENT MOMENTS</div><h3>THE CHRONICLE</h3></div></div><div v-if="!data.events.length" class="empty-state">No events synced yet.</div><div v-else class="timeline"><div v-for="event in data.events.slice(0,5)" :key="event.title"><span class="event-icon death">✦</span><p><b>{{event.title}}</b><small>{{event.detail}}</small></p></div></div></article></section><section v-if="route==='chronicle'" class="panel chronicle-page"><div class="panel-title"><div><div class="kicker">ALL GUILD EVENTS</div><h3>THE CHRONICLE</h3></div></div><div v-if="!data.events.length" class="empty-state">No events synced yet. Your guild story will appear here.</div><div v-else class="timeline"><div v-for="event in data.events" :key="event.title"><span class="event-icon death">✦</span><p><b>{{event.title}}</b><small>{{event.detail}}</small></p></div></div></section></main><footer><span>© 2026 CZECHDREAM FOREVER</span><span>PUBLIC GUILD CHRONICLE · AZEROTH</span></footer></div></template>
